trusted_signatures = ["json", "yaml"]

def deserialize_data(data, signature="json"):
    """
    Deserialize data from an untrusted source into a Python object.

    Only formats listed in ``trusted_signatures`` are accepted. Formats that
    can execute arbitrary code during deserialization (e.g. pickle) are
    intentionally not supported.
    """
    if not isinstance(signature, str) or signature not in trusted_signatures:
        raise ValueError(f"Unsupported or untrusted format: {signature!r}")

    if isinstance(data, (bytes, bytearray)):
        try:
            data = bytes(data).decode("utf-8")
        except UnicodeDecodeError as exc:
            raise ValueError("Data must be valid UTF-8 text") from exc
    elif not isinstance(data, str):
        raise TypeError("Data must be str or bytes")

    if signature == "json":
        import json
        return json.loads(data)
    elif signature == "yaml":
        import yaml
        # safe_load only constructs basic Python objects (no arbitrary code execution)
        return yaml.safe_load(data)

    # Defensive fallback; should be unreachable due to the whitelist check above.
    raise ValueError(f"Unsupported or untrusted format: {signature!r}")
