_IDENTIFIER_RE = re.compile(r'^[A-Za-z_][A-Za-z0-9_]*$')
_CONDITION_RE = re.compile(
    r'^\s*([A-Za-z_][A-Za-z0-9_]*)\s*(==|!=|<>|<=|>=|=|<|>)\s*(.+?)\s*$'
)
_LITERAL_KEYWORDS = {'true': True, 'false': False, 'null': None, 'none': None}


def _parse_operand(token):
    """Parse a right-hand operand into ('literal', value) or ('field', name)."""
    token = token.strip()
    lowered = token.lower()
    if lowered in _LITERAL_KEYWORDS:
        return ('literal', _LITERAL_KEYWORDS[lowered])
    try:
        value = ast.literal_eval(token)
    except (ValueError, SyntaxError):
        value = None
    else:
        if isinstance(value, (int, float, str, bool)) or value is None:
            return ('literal', value)
        raise ValueError(f"Unsupported literal in WHERE clause: {token!r}")
    if _IDENTIFIER_RE.match(token):
