            direction = order_parts[1].upper()
            if direction not in ('ASC', 'DESC'):
                raise ValueError("Invalid ORDER BY direction")
            reverse = direction == 'DESC'

        # Execute the query
        result = filter(filter_func, data)
        result = sorted(result, key=lambda x: x[order_by_field], reverse=reverse)
        result = [{field: item[field] for field in select_fields} for item in result]

        return result

    except Exception as e:
